// Generated from packages/desktop/crates/theme/assets/material/icons.json (Material Icon Theme): the file names and
// extensions with an icon of their own. One string each, split on first use, so the compiler doesn't type-check
// thousands of literals.

enum FileIcons {
    static let names: Set<Substring> = Set(namesList.split(separator: " "))
    static let extensions: Set<Substring> = Set(extensionsList.split(separator: " "))

    /// Whether the icon theme has its own icon for the last component of `path`: its whole name, else any of its extensions.
    static func has(_ path: String) -> Bool {
        let name = Substring((path.split(separator: "/", omittingEmptySubsequences: false).last ?? Substring(path)).lowercased())
        if names.contains(name) { return true }
        var rest = name[...]
        while let dot = rest.firstIndex(of: ".") {
            rest = rest[rest.index(after: dot)...]
            if extensions.contains(rest) { return true }
        }
        return false
    }

